void threeWayPartition_6(vector<int>& a, int pivot) { int lo = 0, i = 0, hi = (int)a.size() - 1; while (i <= hi) { if (a[i] < pivot) { int tmp = a[lo]; a[lo] = a[i]; a[i] = tmp; ++lo; ++i; } else if (a[i] > pivot) { int tmp = a[i]; a[i] = a[hi]; a[hi] = tmp; --hi; } else ++i; } }
long long maxSumWindow_7(const vector<int>& a, int k) { int n = (int)a.size(); long long s = 0; for (int i = 0; i < k; ++i) s += a[i]; long long best = s; for (int i = k; i < n; ++i) { s += a[i] - a[i - k]; if (s > best) best = s; } return best; }
long long minSumWindow_7(const vector<int>& a, int k) { int n = (int)a.size(); long long s = 0; for (int i = 0; i < k; ++i) s += a[i]; long long best = s; for (int i = k; i < n; ++i) { s += a[i] - a[i - k]; if (s < best) best = s; } return best; }
pair<int, int> twoSumPair_7(const vector<int>& a, int t) { int lo = 0, hi = (int)a.size() - 1; while (lo < hi) { int s = a[lo] + a[hi]; if (s == t) return make_pair(lo, hi); if (s < t) ++lo; else --hi; } return make_pair(-1, -1); }
bool isPalindromeVec_7(const vector<int>& a) { int lo = 0, hi = (int)a.size() - 1; while (lo < hi) { if (a[lo] != a[hi]) return false; ++lo; --hi; } return true; }
void reverseInPlace_7(vector<int>& a) { int lo = 0, hi = (int)a.size() - 1; while (lo < hi) { int tmp = a[lo]; a[lo] = a[hi]; a[hi] = tmp; ++lo; --hi; } }
void partitionEvenOdd_7(vector<int>& a) { int lo = 0, hi = (int)a.size() - 1; while (lo < hi) { if (a[lo] % 2 == 0) ++lo; else { int tmp = a[lo]; a[lo] = a[hi]; a[hi] = tmp; --hi; } } }
int removeDuplicates_7(vector<int>& a) { int write = 0; for (int read = 0; read < (int)a.size(); ++read) { if (read == 0 || a[read] != a[read - 1]) a[write++] = a[read]; } return write; }
void moveZeroes_7(vector<int>& a) { int write = 0; for (int read = 0; read < (int)a.size(); ++read) { if (a[read] != 0) { a[write] = a[read]; ++write; } } while (write < (int)a.size()) { a[write] = 0; ++write; } }
vector<int> mergeSortedVec_7(const vector<int>& a, const vector<int>& b) { vector<int> r; int i = 0, j = 0; while (i < (int)a.size() && j < (int)b.size()) { if (a[i] <= b[j]) r.push_back(a[i++]); else r.push_back(b[j++]); } while (i < (int)a.size()) r.push_back(a[i++]); while (j < (int)b.size()) r.push_back(b[j++]); return r; }
int positiveWindows_7(const vector<int>& a, int k) { int n = (int)a.size(); long long s = 0; for (int i = 0; i < k; ++i) s += a[i]; int count = s > 0 ? 1 : 0; for (int i = k; i < n; ++i) { s += a[i] - a[i - k]; if (s > 0) ++count; } return count; }
void rotateArraySteps_7(vector<int>& a, int k) { int n = a.size(); if (n == 0) return; for (int r = 0; r < k; ++r) { int last = a[n - 1]; for (int i = n - 1; i > 0; --i) a[i] = a[i - 1]; a[0] = last; } }
void threeWayPartition_7(vector<int>& a, int pivot) { int lo = 0, i = 0, hi = (int)a.size() - 1; while (i <= hi) { if (a[i] < pivot) { int tmp = a[lo]; a[lo] = a[i]; a[i] = tmp; ++lo; ++i; } else if (a[i] > pivot) { int tmp = a[i]; a[i] = a[hi]; a[hi] = tmp; --hi; } else ++i; } }
